// Sound-effect cues: [frame relative to the scene start, file name in public/<slug>/sfx (no extension), volume 0-1]
// Put each cue on the frame of the visual event (impact, slam, card pop...), not "around" it.
//
// Available names (generated by gen_audio.py):
//   whoosh whoosh_long swish thud impact pop slam punch ding kaching stamp shatter
//   explosion missile tick riser freeze page boing clink scribble horn buzz swirl
//   crash chains gold stinger
export type SfxCue = [number, string, number?];

export const range = (from: number, n: number, step: number, name: string, vol = 1): SfxCue[] =>
  Array.from({ length: n }, (_, i) => [from + i * step, name, vol] as SfxCue);

// chapter cards: orchestral hit + swoosh of the title bar
export const CARD: SfxCue[] = [
  [0, "stinger", 0.8],
  [8, "whoosh", 0.5],
];
